import React, { useState, useEffect } from 'react';
import { I18nextProvider } from 'react-i18next';
import { ThemeProvider } from '@mui/material/styles';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import i18n from './i18n';
import theme from './theme/theme';
import { CircularProgress, Box } from '@mui/material';

// Auth
import Login from './components/auth/Login';

// Layout components
import Header from './components/layout/Header';
import Footer from './components/layout/Footer';

// Pages
import HomePage from './components/pages/HomePage';
import ProfessionalHomePage from './components/pages/ProfessionalHomePage';
import AboutPage from './components/pages/AboutPage';
import ProfessionalAboutPage from './components/pages/ProfessionalAboutPage';
import TeamMembers from './components/pages/TeamMembers';
import EventsPage from './components/pages/EventsPage';
import ProfessionalEventsPage from './components/pages/ProfessionalEventsPage';
import EventDetailPage from './components/pages/EventDetailPage';
import MinistriesPage from './components/pages/MinistriesPage';
import ProfessionalMinistriesPage from './components/pages/ProfessionalMinistriesPage';
import ProfessionalChildrenMinistryPage from './components/pages/ProfessionalChildrenMinistryPage';
import ProfessionalYouthMinistryPage from './components/pages/ProfessionalYouthMinistryPage';
import ProfessionalMenMinistryPage from './components/pages/ProfessionalMenMinistryPage';
import ProfessionalWomenMinistryPage from './components/pages/ProfessionalWomenMinistryPage';
import ProfessionalYoungCouplesMinistryPage from './components/pages/ProfessionalYoungCouplesMinistryPage';
import YouthMinistryPage from './components/pages/YouthMinistryPage';
import WomenMinistryPage from './components/pages/WomenMinistryPage';
import MenMinistryPage from './components/pages/MenMinistryPage';
import ChildrenMinistryPage from './components/pages/ChildrenMinistryPage';
import YoungCouplesMinistryPage from './components/pages/YoungCouplesMinistryPage';
import SermonsPage from './components/pages/SermonsPage';
import ProfessionalSermonsPage from './components/pages/ProfessionalSermonsPage';
import ContactPageSimple from './components/pages/ContactPageSimple';
import ProfessionalContactPage from './components/pages/ProfessionalContactPage';
import GivingPage from './components/pages/GivingPage';
import ZellePage from './components/pages/ZellePage';
import GetInvolvedPage from './components/pages/GetInvolvedPage';
import NotFoundPage from './components/pages/NotFoundPage';

function App() {
  const [key, setKey] = useState(0);

  useEffect(() => {
    // Force re-render when language changes
    const handleLanguageChanged = () => {
      setKey(prevKey => prevKey + 1);
    };

    i18n.on('languageChanged', handleLanguageChanged);

    return () => {
      i18n.off('languageChanged', handleLanguageChanged);
    };
  }, []);

  // Simple loading component
  const PageLoading = () => (
    <Box 
      display="flex" 
      justifyContent="center" 
      alignItems="center" 
      minHeight="100vh"
    >
      <CircularProgress />
    </Box>
  );

  return (
    <I18nextProvider i18n={i18n}>
      <ThemeProvider theme={theme}>
        <Router>
          <div className="App" style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
            <Header />
            <main style={{ flex: 1 }}>
              <Routes>
                  {/* Public Routes */}
                  <Route path="/" element={<ProfessionalHomePage />} />
                  <Route path="/home-old" element={<HomePage />} />
                  <Route path="/about" element={<ProfessionalAboutPage />} />
                  <Route path="/about-old" element={<AboutPage />} />
                  <Route path="/notre-equipe" element={<TeamMembers />} />
                  <Route path="/events" element={<ProfessionalEventsPage />} />
                  <Route path="/events-old" element={<EventsPage />} />
                  <Route path="/evenements/:id" element={<EventDetailPage />} />
                  <Route path="/ministries" element={<ProfessionalMinistriesPage />} />
                  <Route path="/ministries-old" element={<MinistriesPage />} />
                  <Route path="/children-ministry" element={<ProfessionalChildrenMinistryPage />} />
                  <Route path="/children-ministry-old" element={<ChildrenMinistryPage />} />
                  <Route path="/youth-ministry" element={<ProfessionalYouthMinistryPage />} />
                  <Route path="/youth-ministry-old" element={<YouthMinistryPage />} />
                  <Route path="/women-ministry" element={<ProfessionalWomenMinistryPage />} />
                  <Route path="/women-ministry-old" element={<WomenMinistryPage />} />
                  <Route path="/men-ministry" element={<ProfessionalMenMinistryPage />} />
                  <Route path="/men-ministry-old" element={<MenMinistryPage />} />
                  <Route path="/young-couples-ministry" element={<ProfessionalYoungCouplesMinistryPage />} />
                  <Route path="/young-couples-ministry-old" element={<YoungCouplesMinistryPage />} />
                  <Route path="/sermons" element={<ProfessionalSermonsPage />} />
                  <Route path="/sermons-old" element={<SermonsPage />} />
                  <Route path="/contact" element={<ProfessionalContactPage />} />
                  <Route path="/contact-old" element={<ContactPageSimple />} />
                  <Route path="/giving" element={<GivingPage />} />
                  <Route path="/zelle" element={<ZellePage />} />
                  <Route path="/get-involved" element={<GetInvolvedPage />} />

                  {/* Auth Routes */}
                  <Route path="/login" element={<Login />} />

                  {/* 404 Route */}
                  <Route path="*" element={<NotFoundPage />} />
                </Routes>
              </main>
              <Footer />
            </div>
          </Router>
        </ThemeProvider>
      </I18nextProvider>
    );
};

export default App;

import React, { useEffect } from 'react';
import { I18nextProvider } from 'react-i18next';
import { ThemeProvider } from '@mui/material/styles';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import i18n from './i18n';
import theme from './theme/theme';

// Auth
import Login from './components/auth/Login';

// Layout components
import Header from './components/layout/Header';
import Footer from './components/layout/Footer';

// Pages
import HomePage from './components/pages/HomePage';
import ProfessionalHomePage from './components/pages/ProfessionalHomePage';
import AboutPage from './components/pages/AboutPage';
import ProfessionalAboutPage from './components/pages/ProfessionalAboutPage';
import TeamMembers from './components/pages/TeamMembers';
import EventsPage from './components/pages/EventsPage';
import ProfessionalEventsPage from './components/pages/ProfessionalEventsPage';
import EventDetailPage from './components/pages/EventDetailPage';
import MinistriesPage from './components/pages/MinistriesPage';
import ProfessionalMinistriesPage from './components/pages/ProfessionalMinistriesPage';
import ProfessionalChildrenMinistryPage from './components/pages/ProfessionalChildrenMinistryPage';
import ProfessionalYouthMinistryPage from './components/pages/ProfessionalYouthMinistryPage';
import ProfessionalMenMinistryPage from './components/pages/ProfessionalMenMinistryPage';
import ProfessionalWomenMinistryPage from './components/pages/ProfessionalWomenMinistryPage';
import ProfessionalYoungCouplesMinistryPage from './components/pages/ProfessionalYoungCouplesMinistryPage';
import YouthMinistryPage from './components/pages/YouthMinistryPage';
import WomenMinistryPage from './components/pages/WomenMinistryPage';
import MenMinistryPage from './components/pages/MenMinistryPage';
import ChildrenMinistryPage from './components/pages/ChildrenMinistryPage';
import YoungCouplesMinistryPage from './components/pages/YoungCouplesMinistryPage';
import SermonsPage from './components/pages/SermonsPage';
import ProfessionalSermonsPage from './components/pages/ProfessionalSermonsPage';
import ContactPageSimple from './components/pages/ContactPageSimple';
import ProfessionalContactPage from './components/pages/ProfessionalContactPage';
import GivingPage from './components/pages/GivingPage';
import ZellePage from './components/pages/ZellePage';
import GetInvolvedPage from './components/pages/GetInvolvedPage';
import NotFoundPage from './components/pages/NotFoundPage';

function App() {
  useEffect(() => {
    // Force re-render when language changes
    const handleLanguageChanged = () => {
      // Removed setKey call as key is not used
      // Perhaps re-render is not needed, or use a different method
    };

    i18n.on('languageChanged', handleLanguageChanged);

    return () => {
      i18n.off('languageChanged', handleLanguageChanged);
    };
  }, []);

  return (
    <I18nextProvider i18n={i18n}>
      <ThemeProvider theme={theme}>
        <Router>
          <div className="App" style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
            <Header />
            <main style={{ flex: 1 }}>
              <Routes>
                  {/* Public Routes */}
                  <Route path="/" element={<ProfessionalHomePage />} />
                  <Route path="/home-old" element={<HomePage />} />
                  <Route path="/about" element={<ProfessionalAboutPage />} />
                  <Route path="/about-old" element={<AboutPage />} />
                  <Route path="/notre-equipe" element={<TeamMembers />} />
                  <Route path="/events" element={<ProfessionalEventsPage />} />
                  <Route path="/events-old" element={<EventsPage />} />
                  <Route path="/evenements/:id" element={<EventDetailPage />} />
                  <Route path="/ministries" element={<ProfessionalMinistriesPage />} />
                  <Route path="/ministries-old" element={<MinistriesPage />} />
                  <Route path="/children-ministry" element={<ProfessionalChildrenMinistryPage />} />
                  <Route path="/children-ministry-old" element={<ChildrenMinistryPage />} />
                  <Route path="/youth-ministry" element={<ProfessionalYouthMinistryPage />} />
                  <Route path="/youth-ministry-old" element={<YouthMinistryPage />} />
                  <Route path="/women-ministry" element={<ProfessionalWomenMinistryPage />} />
                  <Route path="/women-ministry-old" element={<WomenMinistryPage />} />
                  <Route path="/men-ministry" element={<ProfessionalMenMinistryPage />} />
                  <Route path="/men-ministry-old" element={<MenMinistryPage />} />
                  <Route path="/young-couples-ministry" element={<ProfessionalYoungCouplesMinistryPage />} />
                  <Route path="/young-couples-ministry-old" element={<YoungCouplesMinistryPage />} />
                  <Route path="/sermons" element={<ProfessionalSermonsPage />} />
                  <Route path="/sermons-old" element={<SermonsPage />} />
                  <Route path="/contact" element={<ProfessionalContactPage />} />
                  <Route path="/contact-old" element={<ContactPageSimple />} />
                  <Route path="/giving" element={<GivingPage />} />
                  <Route path="/zelle" element={<ZellePage />} />
                  <Route path="/get-involved" element={<GetInvolvedPage />} />

                  {/* Auth Routes */}
                  <Route path="/login" element={<Login />} />

                  {/* 404 Route */}
                  <Route path="*" element={<NotFoundPage />} />
                </Routes>
              </main>
              <Footer />
            </div>
          </Router>
        </ThemeProvider>
      </I18nextProvider>
    );
};

export default App;

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { 
    Box, 
    Typography, 
    Card, 
    CardContent, 
    Button, 
    useTheme, 
    useMediaQuery,
    Modal,
    IconButton,
    styled
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import EventIcon from '@mui/icons-material/Event';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import CloseIcon from '@mui/icons-material/Close';

const EventBoxes = () => {
    const { t } = useTranslation();
    const [selectedEvent, setSelectedEvent] = useState(null);
    const [open, setOpen] = useState(false);
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('md'));

    const handleOpen = (event) => {
        setSelectedEvent(event);
        setOpen(true);
    };

    const handleClose = () => {
        setOpen(false);
    };

    const events = [
        {
            id: 1,
            title: t('events.multimedia.title', 'Multimedia Ministry'),
            date: t('events.multimedia.date', 'Sunday, 10:00 AM - 12:00 PM'),
            location: t('events.multimedia.location', 'Main Sanctuary'),
            description: t('events.multimedia.description', 'The Multimedia Ministry is dedicated to using technology and creativity to support and enhance worship experience. Through sound, visuals, and digital media, we help communicate the message of the Gospel clearly and effectively to both in-person and online audiences. "Go into all the world and preach the gospel to all creation." — Mark 16:15'),
            image: '/images/easter/multimedia-photo.jpg',
            category: t('events.multimedia.category', 'Technology & Worship'),
            registrationUrl: null // No registration needed for regular services
        },
        {
            id: 2,
            title: t('events.fellowship.title', 'Community Fellowship Gathering'),
            date: t('events.fellowship.date', 'Wednesdays 6:30 PM'),
            location: t('events.fellowship.location', 'Fellowship Hall'),
            description: t('events.fellowship.description', 'Connect with our church family through meaningful fellowship, prayer, and building lasting relationships in Christ.'),
            image: '/images/easter/worship-photo.jpg',
            category: t('events.fellowship.category', 'Fellowship'),
            registrationUrl: 'https://onrealm.org/fbckissimmee/PublicRegistrations/Event?linkString=N2Y4NmNiNzctOTVlMC00MjE3LWFjOGEtYjNjYTAxNWU2MGRl'
        },
        {
            id: 3,
            title: t('events.bridge.title', 'Bridge Ministry'),
            date: t('events.bridge.date', 'Starting April 1'),
            location: t('events.bridge.location', 'Education Wing'),
            description: t('events.bridge.description', 'Connecting youth to God, the church, and one another. We serve as a welcoming pathway for new visitors and the surrounding community by building meaningful relationships and providing support where needed most. "Therefore welcome one another as Christ has welcomed you, for the glory of God." — Romans 15:7'),
            image: '/images/easter/bridge-ministry-photo.jpg',
            category: t('events.bridge.category', 'Youth & Community'),
            registrationUrl: 'https://onrealm.org/fbckissimmee/PublicRegistrations/Event?linkString=N2Y4NmNiNzctOTVlMC00MjE3LWFjOGEtYjNjYTAxNWU2MGRl'
        },
    ];

    return (
        <Box sx={{
            display: 'grid',
            gridTemplateColumns: { xs: '1fr', md: 'repeat(3, 1fr)' },
            gap: 3,
            mt: 4
        }}>
            {events.map((event) => (
                <Card 
                    key={event.id}
                    sx={{
                        height: '100%',
                        display: 'flex',
                        flexDirection: 'column',
                        transition: 'transform 0.3s, box-shadow 0.3s',
                        '&:hover': {
                            transform: 'translateY(-5px)',
                            boxShadow: 3
                        },
                        border: '1px solid',
                        borderColor: 'divider',
                        borderRadius: 2,
                        overflow: 'hidden'
                    }}
                >
                    <Box 
                        sx={{
                            height: '250px',
                            backgroundImage: `url(${event.image})`,
                            backgroundSize: 'cover',
                            backgroundPosition: 'center top',
                            backgroundRepeat: 'no-repeat',
                            position: 'relative',
                            '&:before': {
                                content: '""',
                                position: 'absolute',
                                top: 0,
                                left: 0,
                                right: 0,
                                bottom: 0,
                                background: 'linear-gradient(to bottom, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.7) 100%)',
                            }
                        }}
                    >
                        <Box sx={{
                            position: 'absolute',
                            top: '10px',
                            right: '10px',
                            bgcolor: 'primary.main',
                            color: 'white',
                            px: 1.5,
                            py: 0.5,
                            borderRadius: 1,
                            fontSize: '0.75rem',
                            fontWeight: 600,
                            textTransform: 'uppercase',
                            letterSpacing: '0.5px'
                        }}>
                            {event.category}
                        </Box>
                    </Box>

                    <CardContent sx={{ flexGrow: 1, p: 3, display: 'flex', flexDirection: 'column' }}>
                        <Typography variant="h6" component="h3" gutterBottom sx={{ fontWeight: 600, fontSize: '1.1rem' }}>
                            {event.title}
                        </Typography>

                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, color: 'text.secondary' }}>
                            <EventIcon fontSize="small" sx={{ mr: 1, color: 'primary.main' }} />
                            <Typography variant="body2">{event.date}</Typography>
                        </Box>

                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2, color: 'text.secondary' }}>
                            <LocationOnIcon fontSize="small" sx={{ mr: 1, color: 'primary.main' }} />
                            <Typography variant="body2">{event.location}</Typography>
                        </Box>

                        <Typography variant="body2" color="text.secondary" sx={{ mb: 3, flexGrow: 1 }}>
                            {event.description}
                        </Typography>

                        <Box sx={{ display: 'flex', gap: 1, mt: 'auto', justifyContent: 'center' }}>
                            <Button
                                onClick={() => handleOpen(event)}
                                variant="outlined"
                                size="small"
                                sx={{
                                    textTransform: 'none',
                                    borderRadius: '20px',
                                    px: 2,
                                    py: 0.8,
                                    fontSize: '0.8125rem',
                                    '&:hover': {
                                        backgroundColor: 'primary.light',
                                        color: 'white',
                                        borderColor: 'primary.light',
                                        boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
                                    },
                                    transition: 'all 0.2s ease-in-out'
                                }}
                            >
                                {t('about.learnMore')}
                            </Button>
                        </Box>
                    </CardContent>
                </Card>
            ))}

            {/* Event Preview Modal */}
            <EventPreviewModal 
                open={open} 
                onClose={handleClose} 
                event={selectedEvent} 
                t={t} 
            />
        </Box>
    );
};

// Styled components for the modal
const ModalContent = styled(Box)(({ theme }) => ({
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: '90%',
    maxWidth: '600px',
    maxHeight: '90vh',
    backgroundColor: theme.palette.background.paper,
    boxShadow: theme.shadows[24],
    padding: theme.spacing(4),
    borderRadius: theme.shape.borderRadius,
    outline: 'none',
    overflowY: 'auto',
    [theme.breakpoints.down('sm')]: {
        width: '95%',
        padding: theme.spacing(2),
    },
}));

const CloseButton = styled(IconButton)(({ theme }) => ({
    position: 'absolute',
    right: theme.spacing(1),
    top: theme.spacing(1),
    color: theme.palette.grey[500],
}));

const EventPreviewModal = ({ open, onClose, event, t }) => {
    if (!event) return null;

    return (
        <Modal
            open={open}
            onClose={onClose}
            aria-labelledby="event-preview-title"
            aria-describedby="event-preview-description"
        >
            <ModalContent>
                <CloseButton 
                    aria-label="close" 
                    onClick={onClose}
                    size="large"
                >
                    <CloseIcon />
                </CloseButton>

                <Typography id="event-preview-title" variant="h5" component="h2" gutterBottom>
                    {event.title}
                </Typography>

                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2, color: 'text.secondary' }}>
                    <EventIcon fontSize="small" sx={{ mr: 1, color: 'primary.main' }} />
                    <Typography variant="body2">{event.date}</Typography>
                </Box>

                <Box sx={{ display: 'flex', alignItems: 'center', mb: 3, color: 'text.secondary' }}>
                    <LocationOnIcon fontSize="small" sx={{ mr: 1, color: 'primary.main' }} />
                    <Typography variant="body2">{event.location}</Typography>
                </Box>

                <Typography id="event-preview-description" variant="body1" paragraph>
                    {event.description}
                </Typography>

                <Box sx={{ 
                    display: 'flex', 
                    justifyContent: 'flex-end',
                    mt: 3,
                    pt: 2,
                    borderTop: `1px solid`,
                    borderColor: 'divider'
                }}>
                    <Button 
                        onClick={onClose}
                        variant="contained"
                        color="primary"
                        sx={{ textTransform: 'none' }}
                    >
                        {t('common.close')}
                    </Button>
                </Box>
            </ModalContent>
        </Modal>
    );
};

export default EventBoxes;

