              sx={{ width: 38, height: 38, borderRadius: '50%', objectFit: 'cover' }}
            />
            <Typography
              sx={{
                fontFamily: '"Playfair Display", serif',
                fontWeight: 700,
                fontSize: '0.88rem',
                background: 'linear-gradient(135deg, #1a365d, #c9a84c)',
