          <Typography variant="body1" sx={{ mb: 3, color: 'text.secondary' }}>
            {t('children.readyToJoinDescription')}
          </Typography>
          <Button 
            variant="contained" 
            size="large"
            sx={{ 
              px: 4,
              py: 1.5,
              borderRadius: 2,
              fontWeight: 600,
              textTransform: 'none'
            }}
          >
            {t('children.getConnected')}
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

